-- 关键词（组合 2 + 排除 177 = 179）
DELETE FROM yq_keyword WHERE group_id = 1761600000000000000;

-- 引用计数与关键词库保持一致
UPDATE yq_keyword SET ref_count = (SELECT COUNT(*) FROM yq_task_keyword tk WHERE tk.keyword_id = yq_keyword.keyword_id)
WHERE group_id = 1761600000000000000;

